; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpc (Amstrad CPC - direct hardware, no firmware), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 1		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			di				; (KL ROM SELECT lets interrupts in again)
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 12: Input "How many passes (Return = 5)"; passes
			dw kw_printzoscii
			dw glyph_48, glyph_6F, glyph_77, glyph_20, glyph_6D, glyph_61, glyph_6E, glyph_79
			dw glyph_20, glyph_70, glyph_61, glyph_73, glyph_73, glyph_65, glyph_73, glyph_20
			dw glyph_28, glyph_52, glyph_65, glyph_74, glyph_75, glyph_72, glyph_6E, glyph_20
			dw glyph_3D, glyph_20, glyph_35, glyph_29, glyph_3F, glyph_20, 0		; "How many passes (Return = 5)? "
			dw kw_inputint, var_passes

			; main.bas 13: If passes < 1 Or passes > 100 Then passes = 5
			dw kw_scpltvl, var_passes, 1
			dw kw_ftov, tmp0
			dw kw_scpgtvl, var_passes, 100
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, if1_1
			dw kw_ltov, 5, var_passes
if1_1:

			; main.bas 14: Do
do2_t:

			; main.bas 15: Print
			dw kw_printnl

			; main.bas 16: Print "T = turbo, N = normal, X = exit"
			dw kw_printzoscii
			dw glyph_54, glyph_20, glyph_3D, glyph_20, glyph_74, glyph_75, glyph_72, glyph_62
			dw glyph_6F, glyph_2C, glyph_20, glyph_4E, glyph_20, glyph_3D, glyph_20, glyph_6E
			dw glyph_6F, glyph_72, glyph_6D, glyph_61, glyph_6C, glyph_2C, glyph_20, glyph_58
			dw glyph_20, glyph_3D, glyph_20, glyph_65, glyph_78, glyph_69, glyph_74, 1
			dw 0		; "T = turbo, N = normal, X = exit\n"

			; main.bas 17: Do : k = UCase$(Inkey$) : Frame : Loop Until (k = "T") Or (k = "N") Or (k = "X")
do3_t:
			dw kw_inkeys, stmp0
			dw kw_strucase, stmp0, stmp0
			dw kw_strcpy, var_k, stmp0
			dw kw_frame
			dw kw_strcmpeq, var_k, str0
			dw kw_ftov, tmp0
			dw kw_strcmpeq, var_k, str1
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_strcmpeq, var_k, str2
			dw kw_ftov, tmp1
			dw kw_orvv, tmp0, tmp1, tmp0
			dw kw_goto_ifzero_n, tmp0, do3_t
do3_e:

			; main.bas 18: If k = "X" Then Exit Do
			dw kw_strcmpeq, var_k, str2
			dw kw_goto_iffalse_n, if4_1
			dw do2_e_go
if4_1:

			; main.bas 19: Print IIf(k = "T", "Turbo", "Normal"); ": "; passes; " passes..."
			dw kw_strcmpeq, var_k, str0
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, ch5_0
			dw kw_strcpy, stmp0, str3
			dw ch5_e_go
ch5_0:
			dw kw_strcpy, stmp0, str4
			dw ch5_e_go
ch5_1:
			dw kw_strcpy, stmp0, str5
ch5_e:
			dw kw_printstrvar, stmp0
			dw kw_printzoscii
			dw glyph_3A, glyph_20, 0		; ": "
			dw kw_printint, var_passes
			dw kw_printzoscii
			dw glyph_20, glyph_70, glyph_61, glyph_73, glyph_73, glyph_65, glyph_73, glyph_2E
			dw glyph_2E, glyph_2E, 1, 0		; " passes...\n"

			; main.bas 20: t0 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t0

			; main.bas 21: If k = "T" Then
			dw kw_strcmpeq, var_k, str0
			dw kw_goto_iffalse_n, if6_1

			; main.bas 22: Turbo On
			dw kw_turbo_on

			; main.bas 23: RunPasses
			dw p_runpasses_c

			; main.bas 24: Turbo Off
			dw kw_turbo_off

			; main.bas 25: Else
			dw if6_e_go
if6_1:

			; main.bas 26: RunPasses
			dw p_runpasses_n_c

			; main.bas 27: End If
if6_e:

			; main.bas 28: t1 = Ticks
			dw kw_ticks, tmp0
			dw kw_vtov, tmp0, var_t1

			; main.bas 29: Print "Done - stop the stopwatch"
			dw kw_printzoscii
			dw glyph_44, glyph_6F, glyph_6E, glyph_65, glyph_20, glyph_2D, glyph_20, glyph_73
			dw glyph_74, glyph_6F, glyph_70, glyph_20, glyph_74, glyph_68, glyph_65, glyph_20
			dw glyph_73, glyph_74, glyph_6F, glyph_70, glyph_77, glyph_61, glyph_74, glyph_63
			dw glyph_68, 1, 0		; "Done - stop the stopwatch\n"

			; main.bas 30: Print cnt; " primes below "; TOP
			dw kw_printint, var_cnt
			dw kw_printzoscii
			dw glyph_20, glyph_70, glyph_72, glyph_69, glyph_6D, glyph_65, glyph_73, glyph_20
			dw glyph_62, glyph_65, glyph_6C, glyph_6F, glyph_77, glyph_20, glyph_38, glyph_30
			dw glyph_30, glyph_30, 1, 0		; " primes below 8000\n"

			; main.bas 31: If (k = "N") And (System.TicksPerSecond > 0) Then
			dw kw_strcmpeq, var_k, str1
			dw kw_ftov, tmp0
			dw kw_goto_ifzero_n, tmp0, if7_1

			; main.bas 32: Print "took "; t1 - t0; " ticks = "; (t1 - t0) \ System.TicksPerSecond; "."; ((t1 - t0) Mod System.TicksPerSecond) * 10 \ System.TicksPerSecond; " s"
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_printzoscii
			dw glyph_74, glyph_6F, glyph_6F, glyph_6B, glyph_20, 0		; "took "
			dw kw_printint, tmp0
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_divvl, tmp0, 300, tmp0
			dw kw_printzoscii
			dw glyph_20, glyph_74, glyph_69, glyph_63, glyph_6B, glyph_73, glyph_20, glyph_3D
			dw glyph_20, 0		; " ticks = "
			dw kw_printint, tmp0
			dw kw_subvv, var_t1, var_t0, tmp0
			dw kw_modvl, tmp0, 300, tmp0
			dw kw_mulvl, tmp0, 10, tmp0
			dw kw_divvl, tmp0, 300, tmp0
			dw kw_printzoscii
			dw glyph_2E, 0		; "."
			dw kw_printint, tmp0
			dw kw_printzoscii
			dw glyph_20, glyph_73, 1, 0		; " s\n"

			; main.bas 33: ElseIf k = "T" Then
			dw do2_t_go
if7_1:
			dw kw_strcmpeq, var_k, str0
			dw kw_goto_iffalse_n, do2_t

			; main.bas 34: Print "(turbo runs with interrupts off, so"
			dw kw_printzoscii
			dw glyph_28, glyph_74, glyph_75, glyph_72, glyph_62, glyph_6F, glyph_20, glyph_72
			dw glyph_75, glyph_6E, glyph_73, glyph_20, glyph_77, glyph_69, glyph_74, glyph_68
			dw glyph_20, glyph_69, glyph_6E, glyph_74, glyph_65, glyph_72, glyph_72, glyph_75
			dw glyph_70, glyph_74, glyph_73, glyph_20, glyph_6F, glyph_66, glyph_66, glyph_2C
			dw glyph_20, glyph_73, glyph_6F, 1, 0		; "(turbo runs with interrupts off, so\n"

			; main.bas 35: Print "time it with the stopwatch)"
			dw kw_printzoscii
			dw glyph_74, glyph_69, glyph_6D, glyph_65, glyph_20, glyph_69, glyph_74, glyph_20
			dw glyph_77, glyph_69, glyph_74, glyph_68, glyph_20, glyph_74, glyph_68, glyph_65
			dw glyph_20, glyph_73, glyph_74, glyph_6F, glyph_70, glyph_77, glyph_61, glyph_74
			dw glyph_63, glyph_68, glyph_29, 1, 0		; "time it with the stopwatch)\n"

			; main.bas 36: End If
if7_2:
if7_e:

			; main.bas 37: Loop
			dw do2_t_go
do2_e:

			; main.bas 38: End
			dw kw_stop

; ============================================================
; sub runpasses (turbo mode)
; ============================================================

p_runpasses:

			; main.bas 41: Dim p As Integer

			; main.bas 42: For p = 1 To passes
			dw kw_ltov, 1, var_runpasses_p
			dw kw_vtov, var_passes, for8_l
			dw kw_forupv, var_runpasses_p, for8_l, for8_e
for8_t:

			; main.bas 43: Sieve
			dw p_sieve_c

			; main.bas 44: Next
			dw kw_next1v, var_runpasses_p, for8_l, for8_t
for8_e:
			dw p_runpasses_r

; ============================================================
; sub runpasses (normal mode)
; ============================================================

p_runpasses_n:

			; main.bas 41: Dim p As Integer

			; main.bas 42: For p = 1 To passes
			dw kw_ltov, 1, var_runpasses_p
			dw kw_vtov, var_passes, for9_l
			dw kw_forupv_n, var_runpasses_p, for9_l, for9_e
for9_t:

			; main.bas 43: Sieve
			dw p_sieve_n_c

			; main.bas 44: Next
			dw kw_next1v_n, var_runpasses_p, for9_l, for9_t
for9_e:
			dw p_runpasses_n_r

; ============================================================
; sub sieve (turbo mode)
; ============================================================

p_sieve:

			; main.bas 48: Dim i As Integer, j As Integer

			; main.bas 49: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for10_t:

			; main.bas 50: f(i) = 1
			dw kw_aset8, arr_f, var_sieve_i, lit_1

			; main.bas 51: Next
			dw kw_next1l, var_sieve_i, 8000, for10_t
for10_e:

			; main.bas 52: cnt = 0
			dw kw_ztov, var_cnt

			; main.bas 53: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for11_t:

			; main.bas 54: If f(i) = 1 Then
			dw kw_aget8, arr_f, var_sieve_i, tmp0
			dw kw_cpeqvl, tmp0, 1
			dw kw_goto_iffalse, if12_1

			; main.bas 55: cnt = cnt + 1
			dw kw_inc, var_cnt

			; main.bas 56: j = i + i
			dw kw_add, var_sieve_i, var_sieve_i, var_sieve_j

			; main.bas 57: Do While j <= TOP
do13_t:
			dw kw_scplevl, var_sieve_j, 8000
			dw kw_goto_iffalse, do13_e

			; main.bas 58: f(j) = 0
			dw kw_aset8, arr_f, var_sieve_j, lit_0

			; main.bas 59: j = j + i
			dw kw_add, var_sieve_j, var_sieve_i, var_sieve_j

			; main.bas 60: Loop
			dw do13_t_go
do13_e:

			; main.bas 61: End If
if12_1:

			; main.bas 62: Next
			dw kw_next1l, var_sieve_i, 8000, for11_t
for11_e:
			dw p_sieve_r

; ============================================================
; sub sieve (normal mode)
; ============================================================

p_sieve_n:

			; main.bas 48: Dim i As Integer, j As Integer

			; main.bas 49: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for14_t:

			; main.bas 50: f(i) = 1
			dw kw_aset8, arr_f, var_sieve_i, lit_1

			; main.bas 51: Next
			dw kw_next1l_n, var_sieve_i, 8000, for14_t
for14_e:

			; main.bas 52: cnt = 0
			dw kw_ztov, var_cnt

			; main.bas 53: For i = 2 To TOP
			dw kw_ltov, 2, var_sieve_i
for15_t:

			; main.bas 54: If f(i) = 1 Then
			dw kw_aget8, arr_f, var_sieve_i, tmp0
			dw kw_cpeqvl, tmp0, 1
			dw kw_goto_iffalse_n, if16_1

			; main.bas 55: cnt = cnt + 1
			dw kw_inc, var_cnt

			; main.bas 56: j = i + i
			dw kw_add, var_sieve_i, var_sieve_i, var_sieve_j

			; main.bas 57: Do While j <= TOP
do17_t:
			dw kw_scplevl, var_sieve_j, 8000
			dw kw_goto_iffalse_n, do17_e

			; main.bas 58: f(j) = 0
			dw kw_aset8, arr_f, var_sieve_j, lit_0

			; main.bas 59: j = j + i
			dw kw_add, var_sieve_j, var_sieve_i, var_sieve_j

			; main.bas 60: Loop
			dw do17_t_go
do17_e:

			; main.bas 61: End If
if16_1:

			; main.bas 62: Next
			dw kw_next1l_n, var_sieve_i, 8000, for15_t
for15_e:
			dw p_sieve_n_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

do2_e_go:			ld sp, do2_e
			jp ntc_xn
ch5_e_go:			ld sp, ch5_e
			jp ntc_xn
if6_e_go:			ld sp, if6_e
			jp ntc_xn
do2_t_go:			ld sp, do2_t
			jp ntc_xn
do13_t_go:			ld sp, do13_t
			ret
do17_t_go:			ld sp, do17_t
			jp ntc_xn

p_runpasses_c:		; call runpasses (turbo)
			ld hl, 0
			ld (var_runpasses_p), hl
			ld (p_runpasses_rs), sp
			ld sp, p_runpasses
			ret
p_runpasses_r:		; end of runpasses
			ld sp, (p_runpasses_rs)
			ret
p_runpasses_n_c:		; call runpasses (normal)
			ld hl, 0
			ld (var_runpasses_p), hl
			ld (p_runpasses_rs), sp
			ld sp, p_runpasses_n
			jp ntc_xn
p_runpasses_n_r:		; end of runpasses
			ld sp, (p_runpasses_rs)
			jp ntc_xn
p_sieve_c:		; call sieve (turbo)
			ld hl, 0
			ld (var_sieve_i), hl
			ld hl, 0
			ld (var_sieve_j), hl
			ld (p_sieve_rs), sp
			ld sp, p_sieve
			ret
p_sieve_r:		; end of sieve
			ld sp, (p_sieve_rs)
			ret
p_sieve_n_c:		; call sieve (normal)
			ld hl, 0
			ld (var_sieve_i), hl
			ld hl, 0
			ld (var_sieve_j), hl
			ld (p_sieve_rs), sp
			ld sp, p_sieve_n
			jp ntc_xn
p_sieve_n_r:		; end of sieve
			ld sp, (p_sieve_rs)
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_passes:			dw 0
			db 40			; capacity
var_k:			ds 41
var_t0:			dw 0
var_t1:			dw 0
var_cnt:			dw 0
p_runpasses_rs:			dw 0
var_runpasses_p:			dw 0
for8_l:			dw 0
for9_l:			dw 0
p_sieve_rs:			dw 0
var_sieve_i:			dw 0
var_sieve_j:			dw 0
tmp0:			dw 0
tmp1:			dw 0
			db 255			; capacity
stmp0:			ds 256

; numbers passed by address (read only)
lit_1:			dw 1
lit_0:			dw 0

